starterCode:
# 酸碱中和探索台
acid = 8   # 滴入盐酸量（碱原有10）

hide()
# 烧杯中的 NaOH（10 份）+ 滴入 HCl
base = 10 - acid
if base < 0:
    base = 0
ex = acid - 10
if ex < 0:
    ex = 0
fill_rect(0, 40, 200, 14, "#94a3b8")
if base > 0:
    fill_rect(0, -20 + 60, 170, 70, "#dbeafe")
if base == 0:
    fill_rect(0, -20 + 60, 170, 70, "#fce7f3")
# pH 条
ph = 7
if base > 0:
    ph = 13 - base
if ex > 0:
    ph = 1 + ex
if ex == 0:
    if base == 0:
        ph = 7
fill_rect(0, -120, 360, 16, "#e2e8f0")
pos = -180 + ph * 24
fill_rect(pos, -120, 24, 16, "#dc2626")
write("pH=" + ph, pos + 12, -98, "#dc2626", 12)
write("NaOH + HCl = NaCl + H₂O", -20, 130, "#1d4ed8", 14)
if base > 0:
    write("碱剩 " + base + " 份：碱性，酚酞红", -80, 105, "#be185d", 12)
if base == 0:
    if ex == 0:
        write("恰好中和！pH=7，酚酞刚好褪色", -100, 105, "#16a34a", 12)
if ex > 0:
    write("酸过量 " + ex + " 份：酸性，酚酞无色", -90, 105, "#0369a1", 12)
write("中和反应：酸 + 碱 → 盐 + 水", -90, -150, "#0f172a", 12)

